{"description": "List all assistant turns in transcript", "command": "python3 -c "
import json

transcript_path = '.vf-claude/64136fe95f704d55ba5113b750a39331/projects/-app/4ccecab9-ea03-459f-a56e-353642e71d11.jsonl'
with open(transcript_path) as f:
    for i, line in enumerate(f):
        data = json.loads(line)
        if 'message' in data:
            msg = data['message']
            role = msg.get('role')
            content = msg.get('content', '')
            if role == 'assistant':
                # print summary of assistant turns
                print(f'Turn {i}:')
                if isinstance(content, list):
                    for item in content:
                        if item.get('type') == 'tool_use':
                            print(f'  tool_use: {item.get(\"name\")} {item.get(\"input\", {}).get(\"file_path\", \"\")[:50]}')
                        elif item.get('type') == 'text':
                            print(f'  text: {item.get(\"text\", \"\")[:100]}...')
                elif isinstance(content, str):
                    print(f'  str: {content[:100]}...')
""}

